public void testCanInlineReferenceToFunctionInExpression18() {
    // foo should not be inlined because x() may have side effects
    String code =
        "/** @nosideeffects */ function foo(){return 'foo'};" +
        "function x(){return c};" +
        "c = a;" +
        "b.test = 'b';" +
        "a.test = 'a';" +
        "var a = {}, b = {}, c;" +
        "x().test = foo();";
    helperCanInlineReferenceToFunction(false, code, "foo", InliningMode.INLINE_BLOCK);
}
